gcyV(){return"\u0627\u06cc\u0646 \u0639\u0645\u0644\u06cc\u0627\u062a \u0627\u0644\u0627\u0646 \u0645\u062c\u0627\u0632 \u0646\u06cc\u0633\u062a \u2014 \u062f\u0644\u0627\u06cc\u0644:"},
gcyU(){return"\u067e\u0633 \u0627\u0632 \u0631\u0641\u0639 \u0645\u0648\u0627\u0631\u062f \u0632\u06cc\u0631\u060c \u062f\u06a9\u0645\u0647\u0654 \xab\u0628\u0647\u200c\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06cc \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634\xbb \u0631\u0627 \u0628\u0632\u0646\u06cc\u062f."},
gczd(){return"\u0628\u0647\u200c\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06cc \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634"},
cyS(a){return"\u067e\u0634\u062a\u06cc\u0628\u0627\u0646: "+a},
